#!/bin/sh
# Deskhand agent installer, generated by the Deskhand server at @SERVER@.
# Usage: curl -fsSL @SERVER@/install.sh | sudo sh -s -- ENROLL_TOKEN
set -eu

SERVER='@SERVER@'
TOKEN="${1:-${DESKHAND_TOKEN:-}}"
BIN=/usr/local/bin/deskhand-agent
CONFIG=/etc/deskhand/agent.json

fail() { echo "deskhand: $*" >&2; exit 1; }

[ -n "$TOKEN" ] || fail "no enroll token. Usage: curl -fsSL $SERVER/install.sh | sudo sh -s -- TOKEN"
[ "$(id -u)" = 0 ] || fail "run as root (pipe to 'sudo sh -s -- TOKEN')"

case "$(uname -s)" in
	Linux) os=linux ;;
	Darwin) os=macos ;;
	*) fail "unsupported OS: $(uname -s)" ;;
esac
case "$(uname -m)" in
	x86_64 | amd64) arch=x86_64 ;;
	aarch64 | arm64) arch=aarch64 ;;
	*) fail "unsupported CPU: $(uname -m)" ;;
esac
file="deskhand-agent-$os-$arch"

tmp=$(mktemp)
trap 'rm -f "$tmp"' EXIT
echo "deskhand: downloading $file from $SERVER"
if command -v curl >/dev/null 2>&1; then
	curl -fsSL -o "$tmp" "$SERVER/dl/$file" || fail "download failed: $SERVER/dl/$file"
elif command -v wget >/dev/null 2>&1; then
	wget -qO "$tmp" "$SERVER/dl/$file" || fail "download failed: $SERVER/dl/$file"
else
	fail "needs curl or wget"
fi

mkdir -p "$(dirname "$BIN")" "$(dirname "$CONFIG")"
# Stop a running agent first so the binary can be replaced.
if [ -d /run/systemd/system ] && systemctl is-active --quiet deskhand-agent 2>/dev/null; then
	systemctl stop deskhand-agent
fi
mv "$tmp" "$BIN"
chmod 0755 "$BIN"
trap - EXIT

"$BIN" enroll --server "$SERVER" --token "$TOKEN" --config "$CONFIG"

if [ -d /run/systemd/system ]; then
	cat >/etc/systemd/system/deskhand-agent.service <<UNIT
[Unit]
Description=Deskhand agent
After=network-online.target
Wants=network-online.target

[Service]
ExecStart=$BIN run --config $CONFIG
Restart=always
RestartSec=5
# Remote desktop streams an X11 display. Point DISPLAY (and XAUTHORITY) at the
# desktop to show; shell and jobs work without one.
Environment=DISPLAY=:0

[Install]
WantedBy=multi-user.target
UNIT
	systemctl daemon-reload
	systemctl enable --now deskhand-agent
	echo "deskhand: agent installed and running (systemctl status deskhand-agent)"
else
	echo "deskhand: agent installed to $BIN and enrolled."
	echo "deskhand: no systemd here; start it with: $BIN run --config $CONFIG"
fi
